style.css:
@-moz-document domain("anhanguera.com") {
/* fundo */
body {
    background-color: #fff5f7 !important;
}

/* header */
header {
    background-color: #ffeef2 !important;
}

/* botões */
button {
    background-color: #ffc2d1 !important;
    border-radius: 10px !important;
    border: none !important;
}

button:hover {
    background-color: #ff8fab !important;
}

/* textos */
h1, h2, h3 {
    color: #b03060 !important;
}

/* cards */
div {
    border-radius: 10px;
}
}
